def findNearbyStores(session_id, address_line1=None, address_line2=None, city=None, region=None, postal_code=None, country_code=None, latitude=None, longitude=None, service_method=None, limit=None, **_extra):
    import json, os, datetime, time, math, uuid, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0170000" if __import__("os").path.isdir("./environment_mix/0170000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Request log support (best-effort: only if file exists in DB directory)
    def _log(status, session=None, extra=None):
        latency_ms = int((time.time() - t0) * 1000)
        try:
            files = set(os.listdir(_DB))
        except Exception:
            return
        candidates = [n for n in files if n in ("request_logs.json", "usage.json", "audit_logs.json", "requests.json")]
        if not candidates:
            return
        fname = candidates[0]
        rows = _load(fname)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": "dps_req_" + uuid.uuid4().hex[:24],
            "endpoint": "findNearbyStores",
            "timestamp": now,
            "status": status,
            "latency_ms": latency_ms
        }
        if session:
            row["session_id"] = session.get("id")
        if extra and isinstance(extra, dict):
            row.update(extra)
        rows.append(row)
        _save(fname, rows)

    # Validate inputs
    if not isinstance(session_id, str) or not session_id.strip():
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "session_id must be a non-empty string")

    if service_method is not None:
        if not isinstance(service_method, str) or service_method not in ("delivery", "carryout", "unknown"):
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Unsupported service_method", allowed=["delivery", "carryout", "unknown"])

    if limit is None:
        limit = 10
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50")

    has_coords = latitude is not None or longitude is not None
    has_address = any(x is not None for x in (address_line1, city, region, postal_code, country_code, address_line2))
    if not has_coords and not has_address:
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Either an address or latitude/longitude must be provided")

    if has_coords:
        if latitude is None or longitude is None:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Both latitude and longitude must be provided together")
        if not isinstance(latitude, (int, float)) or not isinstance(longitude, (int, float)):
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "latitude/longitude must be numbers")
        if latitude < -90 or latitude > 90:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "latitude out of range")
        if longitude < -180 or longitude > 180:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "longitude out of range")

    if has_address:
        # Required address components for address-based discovery
        required = {"address_line1": address_line1, "city": city, "region": region, "postal_code": postal_code}
        missing = [k for k, v in required.items() if v is None or (isinstance(v, str) and not v.strip())]
        if missing:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Missing required address components", missing=missing)
        for k, v in (("address_line1", address_line1), ("address_line2", address_line2), ("city", city), ("region", region), ("postal_code", postal_code), ("country_code", country_code)):
            if v is not None and not isinstance(v, str):
                _log("error", extra={"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", f"{k} must be a string if provided")

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
    if not sess:
        _log("error", extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Session not found")

    # Enforce session active & not expired
    try:
        exp = sess.get("expires_at")
        expired = False
        if isinstance(exp, str) and exp.endswith("Z"):
            exp_dt = datetime.datetime.fromisoformat(exp[:-1])
            expired = exp_dt <= datetime.datetime.utcnow().replace(microsecond=0)
        elif isinstance(exp, str):
            exp_dt = datetime.datetime.fromisoformat(exp)
            expired = exp_dt <= datetime.datetime.utcnow().replace(microsecond=0)
        else:
            expired = False
    except Exception:
        expired = False

    if sess.get("status") != "active" or expired:
        # If session is active but expired by time, transition to expired if legal
        if sess.get("status") == "active" and expired:
            sess["status"] = "expired"
            sess["updated_at"] = now
            _save("sessions.json", sessions)
        _log("error", sess, extra={"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Session is not active")

    stores = _load("stores.json")
    if not isinstance(stores, list):
        stores = []

    def _dist_km(lat1, lon1, lat2, lon2):
        # haversine
        r = 6371.0
        p1, p2 = math.radians(lat1), math.radians(lat2)
        dphi = math.radians(lat2 - lat1)
        dl = math.radians(lon2 - lon1)
        a = math.sin(dphi/2)**2 + math.cos(p1)*math.cos(p2)*math.sin(dl/2)**2
        return 2*r*math.atan2(math.sqrt(a), math.sqrt(1-a))

    # "Provider call" simulation based on existing store rows (real effect: upsert and return).
    candidates = [s for s in stores if isinstance(s, dict) and s.get("provider") == "dominos"]
    scored = []
    if has_coords:
        for s in candidates:
            lat = s.get("latitude")
            lon = s.get("longitude")
            if isinstance(lat, (int, float)) and isinstance(lon, (int, float)):
                scored.append((_dist_km(latitude, longitude, float(lat), float(lon)), s))
        scored.sort(key=lambda x: x[0])
        discovered = [s for _, s in scored[: max(limit, 25)]]
    else:
        # Address-based: prefer same postal_code/city/region where available
        pc = (postal_code or "").strip().lower()
        ci = (city or "").strip().lower()
        rg = (region or "").strip().lower()
        def _score(s):
            sc = 0
            if isinstance(s.get("postal_code"), str) and s["postal_code"].strip().lower() == pc:
                sc += 3
            if isinstance(s.get("city"), str) and s["city"].strip().lower() == ci:
                sc += 2
            if isinstance(s.get("region"), str) and s["region"].strip().lower() == rg:
                sc += 1
            return -sc
        discovered = sorted(candidates, key=_score)[: max(limit, 25)]

    # If DB has no stores yet, fabricate none (can't invent provider results)
    # Upsert by (provider, provider_store_number) using "discovered" rows
    updated = False
    returned = []
    for s in discovered[:limit]:
        if not isinstance(s, dict):
            continue
        psn = s.get("provider_store_number")
        if not isinstance(psn, str) or not psn:
            continue
        existing = next((x for x in stores if isinstance(x, dict) and x.get("provider") == "dominos" and x.get("provider_store_number") == psn), None)
        if existing:
            # update non-key fields from provider payload snapshot (here: retain as-is, just bump updated_at)
            existing["updated_at"] = now
            updated = True
            returned.append(existing)
        else:
            # this path unlikely since discovered came from stores; still handle generically
            nid = "dps_store_" + uuid.uuid4().hex[:24]
            row = {
                "id": nid,
                "provider": "dominos",
                "provider_store_number": psn,
                "name": s.get("name"),
                "address_line1": s.get("address_line1"),
                "address_line2": s.get("address_line2"),
                "city": s.get("city"),
                "region": s.get("region"),
                "postal_code": s.get("postal_code"),
                "country_code": s.get("country_code"),
                "phone": s.get("phone"),
                "latitude": s.get("latitude"),
                "longitude": s.get("longitude"),
                "is_open": s.get("is_open"),
                "raw_payload": s.get("raw_payload") if isinstance(s.get("raw_payload"), dict) else {},
                "created_at": now,
                "updated_at": now,
            }
            stores.append(row)
            updated = True
            returned.append(row)

    if updated:
        _save("stores.json", stores)

    # MAY set session current_store_id to first returned store
    if returned:
        sess["current_store_id"] = returned[0].get("id")
        sess["updated_at"] = now
        _save("sessions.json", sessions)

    _log("ok", sess, extra={"result_count": len(returned)})
    return {
        "session_id": session_id,
        "current_store_id": sess.get("current_store_id"),
        "stores": returned,
        "count": len(returned)
    }

def getMenu(store_id, service_method, refresh=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0170000" if __import__("os").path.isdir("./environment_mix/0170000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, extra=None):
        latency_ms = int((time.time() - t0) * 1000)
        try:
            files = set(os.listdir(_DB))
        except Exception:
            return
        candidates = [n for n in files if n in ("request_logs.json", "usage.json", "audit_logs.json", "requests.json")]
        if not candidates:
            return
        fname = candidates[0]
        rows = _load(fname)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": "dps_req_" + uuid.uuid4().hex[:24],
            "endpoint": "getMenu",
            "timestamp": now,
            "status": status,
            "latency_ms": latency_ms,
            "store_id": store_id,
            "service_method": service_method
        }
        if extra and isinstance(extra, dict):
            row.update(extra)
        rows.append(row)
        _save(fname, rows)

    if not isinstance(store_id, str) or not store_id.strip():
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "store_id must be a non-empty string")
    if not isinstance(service_method, str) or service_method not in ("delivery", "carryout", "unknown"):
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Unsupported service_method", allowed=["delivery", "carryout", "unknown"])
    if refresh is not None and not isinstance(refresh, bool):
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "refresh must be a boolean if provided")
    if refresh is None:
        refresh = False

    stores = _load("stores.json")
    if not isinstance(stores, list):
        stores = []
    store = next((s for s in stores if isinstance(s, dict) and s.get("id") == store_id), None)
    if not store:
        _log("error", {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Store not found")

    # No explicit auth model in schema; "accessible" if exists.
    menus = _load("store_menus.json")
    if not isinstance(menus, list):
        menus = []

    active = [m for m in menus if isinstance(m, dict) and m.get("store_id") == store_id and m.get("service_method") == service_method and m.get("status") == "active"]
    # use most recently fetched active menu if multiple
    active.sort(key=lambda x: x.get("fetched_at") or "", reverse=True)
    if active and not refresh:
        _log("ok", {"cache": "hit"})
        return {
            "store_id": store_id,
            "service_method": service_method,
            "menu": active[0]
        }

    # Refresh: fetch from "provider" not possible offline; so only succeed if we can create based on existing payload.
    # We treat the store.raw_payload as source and require it to exist (it is non-nullable).
    raw = store.get("raw_payload")
    if not isinstance(raw, dict):
        _log("error", {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "No provider payload available to derive a menu for this store")

    # Mark previous active menu as stale (legal transition active->stale)
    changed = False
    for m in menus:
        if isinstance(m, dict) and m.get("store_id") == store_id and m.get("service_method") == service_method and m.get("status") == "active":
            m["status"] = "stale"
            m["updated_at"] = now
            changed = True

    # Create new menu row (active)
    mid = "dps_menu_" + uuid.uuid4().hex[:24]
    menu_payload = {
        "provider": "dominos",
        "store": {
            "provider_store_number": store.get("provider_store_number"),
            "name": store.get("name"),
        },
        "service_method": service_method,
        "note": "Menu payload derived from cached store context; offline integration server cannot fetch live menus.",
        "source_store_raw_payload": raw,
    }
    new_row = {
        "id": mid,
        "store_id": store_id,
        "service_method": service_method,
        "currency": None,
        "menu_version": None,
        "status": "active",
        "menu_payload": menu_payload,
        "fetched_at": now,
        "created_at": now,
        "updated_at": now,
    }
    menus.append(new_row)
    changed = True
    if changed:
        _save("store_menus.json", menus)

    _log("ok", {"cache": "refresh"})
    return {
        "store_id": store_id,
        "service_method": service_method,
        "menu": new_row
    }

def createOrder(session_id, store_id, service_method, customer=None, delivery_address=None, coupon_codes=None, special_instructions=None, payment_method=None, payment_payload=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0170000" if __import__("os").path.isdir("./environment_mix/0170000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, session=None, extra=None):
        latency_ms = int((time.time() - t0) * 1000)
        try:
            files = set(os.listdir(_DB))
        except Exception:
            return
        candidates = [n for n in files if n in ("request_logs.json", "usage.json", "audit_logs.json", "requests.json")]
        if not candidates:
            return
        fname = candidates[0]
        rows = _load(fname)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": "dps_req_" + uuid.uuid4().hex[:24],
            "endpoint": "createOrder",
            "timestamp": now,
            "status": status,
            "latency_ms": latency_ms
        }
        if session and isinstance(session, dict):
            row["session_id"] = session.get("id")
        if extra and isinstance(extra, dict):
            row.update(extra)
        rows.append(row)
        _save(fname, rows)

    # Validate inputs
    if not isinstance(session_id, str) or not session_id.strip():
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "session_id must be a non-empty string")
    if not isinstance(store_id, str) or not store_id.strip():
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "store_id must be a non-empty string")
    if not isinstance(service_method, str) or service_method not in ("delivery", "carryout"):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Unsupported service_method", allowed=["delivery", "carryout"])

    if customer is not None and not isinstance(customer, dict):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "customer must be an object if provided")
    if delivery_address is not None and not isinstance(delivery_address, dict):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "delivery_address must be an object if provided")
    if coupon_codes is None:
        coupon_codes = []
    if not isinstance(coupon_codes, list) or any(not isinstance(c, str) for c in coupon_codes):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "coupon_codes must be an array of strings")
    if special_instructions is not None and not isinstance(special_instructions, str):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "special_instructions must be a string if provided")
    if payment_method is not None:
        if not isinstance(payment_method, str) or payment_method not in ("cash", "card", "giftcard", "unknown"):
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Unsupported payment_method", allowed=["cash", "card", "giftcard", "unknown"])
    if payment_payload is not None and not isinstance(payment_payload, dict):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "payment_payload must be an object if provided")
    if payment_payload is not None and payment_method is None:
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "payment_method must be provided when payment_payload is provided")

    if service_method == "delivery" and delivery_address is None:
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "delivery_address is required when service_method=delivery")

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
    if not sess:
        _log("error", extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Session not found")

    # Enforce session active & not expired
    try:
        exp = sess.get("expires_at")
        expired = False
        if isinstance(exp, str) and exp.endswith("Z"):
            exp_dt = datetime.datetime.fromisoformat(exp[:-1])
            expired = exp_dt <= datetime.datetime.utcnow().replace(microsecond=0)
        elif isinstance(exp, str):
            exp_dt = datetime.datetime.fromisoformat(exp)
            expired = exp_dt <= datetime.datetime.utcnow().replace(microsecond=0)
        else:
            expired = False
    except Exception:
        expired = False
    if sess.get("status") != "active" or expired:
        if sess.get("status") == "active" and expired:
            sess["status"] = "expired"
            sess["updated_at"] = now
            _save("sessions.json", sessions)
        _log("error", sess, extra={"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Session is not active")

    stores = _load("stores.json")
    if not isinstance(stores, list):
        stores = []
    store = next((st for st in stores if isinstance(st, dict) and st.get("id") == store_id), None)
    if not store:
        _log("error", sess, extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Store not found")

    orders = _load("orders.json")
    if not isinstance(orders, list):
        orders = []

    # Enforce: Only one active session may reference a given current_order_id at a time.
    # Creating a new order sets current_order_id to new id; that's always unique. But if session already points to an order,
    # ensure no other active session points to it (and keep invariant).
    cur_oid = sess.get("current_order_id")
    if isinstance(cur_oid, str) and cur_oid:
        for s in sessions:
            if isinstance(s, dict) and s.get("id") != sess.get("id") and s.get("status") == "active" and s.get("current_order_id") == cur_oid:
                _log("error", sess, extra={"error_code": "CONFLICT"})
                return _err("CONFLICT", "Another active session already references the current_order_id on this session")

    oid = "dps_ord_" + uuid.uuid4().hex[:24]
    order = {
        "id": oid,
        "session_id": session_id,
        "store_id": store_id,
        "service_method": service_method,
        "status": "draft",
        "customer": customer,
        "delivery_address": delivery_address if service_method == "delivery" else delivery_address,  # allowed to be present; not required for carryout
        "coupon_codes": coupon_codes,
        "special_instructions": special_instructions,
        "validation_result": None,
        "pricing_result": None,
        "total_amount": None,
        "currency": None,
        "payment_method": payment_method,
        "payment_payload": payment_payload,
        "provider_order_id": None,
        "provider_tracking_url": None,
        "placed_at": None,
        "last_tracked_at": None,
        "tracking_state": None,
        "error": None,
        "created_at": now,
        "updated_at": now,
    }

    orders.append(order)
    _save("orders.json", orders)

    sess["current_order_id"] = oid
    sess["current_store_id"] = store_id
    sess["updated_at"] = now
    _save("sessions.json", sessions)

    _log("ok", sess, extra={"order_id": oid})
    return {"order": order, "session": {"id": sess.get("id"), "current_order_id": sess.get("current_order_id"), "current_store_id": sess.get("current_store_id")}}

def addItemToOrder(order_id, product_code, quantity, options=None, item_instructions=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0170000" if __import__("os").path.isdir("./environment_mix/0170000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "addItemToOrder"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s[:-1]) if s.endswith("Z") else datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _choose_logfile():
        try:
            files = set(os.listdir(_DB))
        except Exception:
            files = set()
        for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if cand in files:
                return cand
        return "request_logs.json"

    def _log(status, code=None, session_id=None, order_id_for_log=None, meta=None):
        latency_ms = int((time.time() - t0) * 1000)
        fname = _choose_logfile()
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"dps_req_{uuid.uuid4().hex[:24]}",
            "endpoint": endpoint,
            "timestamp": _iso_now(),
            "status": status,
            "latency_ms": latency_ms,
        }
        if session_id is not None:
            row["session_id"] = session_id
        if order_id_for_log is not None:
            row["order_id"] = order_id_for_log
        if code is not None:
            row["error_code"] = code
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save(fname, logs)

    # Validate inputs
    if not isinstance(order_id, str) or not order_id.strip():
        _log("error", "VALIDATION_ERROR", meta={"field": "order_id"})
        return _err("VALIDATION_ERROR", "order_id must be a non-empty string.", field="order_id")
    if not isinstance(product_code, str) or not product_code.strip():
        _log("error", "VALIDATION_ERROR", order_id_for_log=order_id, meta={"field": "product_code"})
        return _err("VALIDATION_ERROR", "product_code must be a non-empty string.", field="product_code")
    if not isinstance(quantity, int) or isinstance(quantity, bool) or quantity < 1 or quantity > 50:
        _log("error", "VALIDATION_ERROR", order_id_for_log=order_id, meta={"field": "quantity"})
        return _err("VALIDATION_ERROR", "quantity must be an integer between 1 and 50.", field="quantity")
    if options is not None and not isinstance(options, dict):
        _log("error", "VALIDATION_ERROR", order_id_for_log=order_id, meta={"field": "options"})
        return _err("VALIDATION_ERROR", "options must be an object if provided.", field="options")
    if item_instructions is not None and not isinstance(item_instructions, str):
        _log("error", "VALIDATION_ERROR", order_id_for_log=order_id, meta={"field": "item_instructions"})
        return _err("VALIDATION_ERROR", "item_instructions must be a string if provided.", field="item_instructions")

    orders = _load("orders.json")
    if not isinstance(orders, list):
        orders = []
    order = next((o for o in orders if isinstance(o, dict) and o.get("id") == order_id), None)
    if not order:
        _log("error", "NOT_FOUND", order_id_for_log=order_id)
        return _err("NOT_FOUND", "Order not found.", order_id=order_id)

    # Ambient auth: choose a valid active session that references this order OR owns it
    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    now = datetime.datetime.utcnow()

    def _session_ok(s):
        if not isinstance(s, dict):
            return False
        if s.get("status") != "active":
            return False
        exp = _parse_dt(s.get("expires_at"))
        if exp is not None and exp <= now:
            return False
        return True

    # Prefer session that has current_order_id = order_id (common in this integration)
    sess = next((s for s in sessions if _session_ok(s) and s.get("current_order_id") == order_id), None)
    if sess is None:
        # Fallback: session that owns the order (orders.session_id)
        sess = next((s for s in sessions if _session_ok(s) and s.get("id") == order.get("session_id")), None)
    if sess is None:
        _log("error", "UNAUTHORIZED", order_id_for_log=order_id)
        return _err("UNAUTHORIZED", "No active session is authorized for this order.", order_id=order_id)

    # Enforce: order belongs to the session attempting mutations
    if order.get("session_id") != sess.get("id"):
        _log("error", "UNAUTHORIZED", session_id=sess.get("id"), order_id_for_log=order_id)
        return _err("UNAUTHORIZED", "Order is not accessible to this session.", order_id=order_id)

    if order.get("status") not in ("draft", "validated", "priced"):
        _log("error", "CONFLICT", session_id=sess.get("id"), order_id_for_log=order_id,
             meta={"rule": "order status must be draft/validated/priced to add items", "status": order.get("status")})
        return _err("CONFLICT", "Order is not in a mutable state for adding items.", order_id=order_id, status=order.get("status"))

    # Create item
    order_items = _load("order_items.json")
    if not isinstance(order_items, list):
        order_items = []

    now_iso = _iso_now()
    new_id = f"dps_item_{uuid.uuid4().hex[:24]}"
    # Ensure uniqueness in file
    existing_ids = {it.get("id") for it in order_items if isinstance(it, dict)}
    while new_id in existing_ids:
        new_id = f"dps_item_{uuid.uuid4().hex[:24]}"

    item = {
        "id": new_id,
        "order_id": order_id,
        "status": "active",
        "product_code": product_code.strip(),
        "quantity": quantity,
        "options": options if isinstance(options, dict) else None,
        "item_instructions": item_instructions,
        "priced_amount": None,
        "currency": None,
        "provider_item_ref": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    order_items.append(item)
    _save("order_items.json", order_items)

    # Touch order updated_at
    order["updated_at"] = now_iso
    _save("orders.json", orders)

    # Return updated order state (order + non-removed items)
    active_items = [it for it in order_items if isinstance(it, dict) and it.get("order_id") == order_id and it.get("status") != "removed"]
    resp = {"order": order, "items": active_items, "added_item_id": new_id}

    _log("ok", session_id=sess.get("id"), order_id_for_log=order_id, meta={"added_item_id": new_id})
    return resp

def removeItemFromOrder(order_id, order_item_id, **_extra):
