            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "removeItemFromOrder"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s[:-1]) if s.endswith("Z") else datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _choose_logfile():
        try:
            files = set(os.listdir(_DB))
        except Exception:
            files = set()
        for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if cand in files:
                return cand
        return "request_logs.json"

    def _log(status, code=None, session_id=None, order_id_for_log=None, meta=None):
        latency_ms = int((time.time() - t0) * 1000)
        fname = _choose_logfile()
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"dps_req_{uuid.uuid4().hex[:24]}",
            "endpoint": endpoint,
            "timestamp": _iso_now(),
            "status": status,
            "latency_ms": latency_ms,
        }
        if session_id is not None:
            row["session_id"] = session_id
        if order_id_for_log is not None:
            row["order_id"] = order_id_for_log
        if code is not None:
            row["error_code"] = code
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save(fname, logs)

    # Validate basic input types; DO NOT reject by strict pattern (audit showed real calls may pass wrong prefixes)
    if not isinstance(order_id, str) or not order_id.strip():
        _log("error", "VALIDATION_ERROR", meta={"field": "order_id"})
        return _err("VALIDATION_ERROR", "order_id must be a non-empty string.", field="order_id")
    if not isinstance(order_item_id, str) or not order_item_id.strip():
        _log("error", "VALIDATION_ERROR", order_id_for_log=order_id, meta={"field": "order_item_id"})
        return _err("VALIDATION_ERROR", "order_item_id must be a non-empty string.", field="order_item_id")

    orders = _load("orders.json")
    if not isinstance(orders, list):
        orders = []
    order = next((o for o in orders if isinstance(o, dict) and o.get("id") == order_id), None)
    if not order:
        _log("error", "NOT_FOUND", order_id_for_log=order_id)
        return _err("NOT_FOUND", "Order not found.", order_id=order_id)

    # Ambient auth: active session referencing this order OR owning it
    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    now = datetime.datetime.utcnow()

    def _session_ok(s):
        if not isinstance(s, dict):
            return False
        if s.get("status") != "active":
            return False
        exp = _parse_dt(s.get("expires_at"))
        if exp is not None and exp <= now:
            return False
        return True

    sess = next((s for s in sessions if _session_ok(s) and s.get("current_order_id") == order_id), None)
    if sess is None:
        sess = next((s for s in sessions if _session_ok(s) and s.get("id") == order.get("session_id")), None)
    if sess is None:
        _log("error", "UNAUTHORIZED", order_id_for_log=order_id)
        return _err("UNAUTHORIZED", "No active session is authorized for this order.", order_id=order_id)

    if order.get("session_id") != sess.get("id"):
        _log("error", "UNAUTHORIZED", session_id=sess.get("id"), order_id_for_log=order_id)
        return _err("UNAUTHORIZED", "Order is not accessible to this session.", order_id=order_id)

    if order.get("status") in ("placing", "placed", "cancelled"):
        _log("error", "CONFLICT", session_id=sess.get("id"), order_id_for_log=order_id,
             meta={"rule": "cannot remove items when order is placing/placed/cancelled", "status": order.get("status")})
        return _err("CONFLICT", "Order is not in a mutable state for removing items.", order_id=order_id, status=order.get("status"))

    order_items = _load("order_items.json")
    if not isinstance(order_items, list):
        order_items = []

    target = None
    for it in order_items:
        if isinstance(it, dict) and it.get("id") == order_item_id and it.get("order_id") == order_id:
            target = it
            break
    if not target:
        _log("error", "NOT_FOUND", session_id=sess.get("id"), order_id_for_log=order_id, meta={"order_item_id": order_item_id})
        return _err("NOT_FOUND", "Order item not found on this order.", order_id=order_id, order_item_id=order_item_id)

    # Idempotent: if already removed, return updated state without error
    now_iso = _iso_now()
    if target.get("status") == "removed":
        order["updated_at"] = now_iso
        _save("orders.json", orders)
        items_non_removed = [it for it in order_items if isinstance(it, dict) and it.get("order_id") == order_id and it.get("status") != "removed"]
        _log("ok", session_id=sess.get("id"), order_id_for_log=order_id, meta={"order_item_id": order_item_id, "idempotent": True})
        return {"order": order, "items": items_non_removed, "removed_item_id": order_item_id, "idempotent": True}

    # Transition active -> removed only
    if target.get("status") != "active":
        _log("error", "INVALID_TRANSITION", session_id=sess.get("id"), order_id_for_log=order_id,
             meta={"from": target.get("status"), "to": "removed", "order_item_id": order_item_id})
        return _err("INVALID_TRANSITION", "Order item cannot be removed from its current state.", order_item_id=order_item_id, from_status=target.get("status"), to_status="removed")

    target["status"] = "removed"
    target["updated_at"] = now_iso
    _save("order_items.json", order_items)

    order["updated_at"] = now_iso
    _save("orders.json", orders)

    items_non_removed = [it for it in order_items if isinstance(it, dict) and it.get("order_id") == order_id and it.get("status") != "removed"]
    _log("ok", session_id=sess.get("id"), order_id_for_log=order_id, meta={"removed_item_id": order_item_id})
    return {"order": order, "items": items_non_removed, "removed_item_id": order_item_id}

def getOrderState(session_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0170000" if __import__("os").path.isdir("./environment_mix/0170000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getOrderState"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, session_id=None, order_id=None, extra=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"dps_log_{int(time.time()*1000)}_{os.getpid()}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "session_id": session_id,
            "order_id": order_id,
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(session_id, str) or not session_id or len(session_id) > 200:
        _log("VALIDATION_ERROR", session_id=session_id)
        return _err("VALIDATION_ERROR", "session_id must be a non-empty string.")
    if not re.match(r"^dps_sess_[A-Za-z0-9]+$", session_id):
        _log("VALIDATION_ERROR", session_id=session_id)
        return _err("VALIDATION_ERROR", "session_id has invalid format.", field="session_id")

    sessions = _load("sessions.json")
    orders = _load("orders.json")
    items = _load("order_items.json")

    sess = next((s for s in sessions if s.get("id") == session_id), None)
    if not sess:
        _log("NOT_FOUND", session_id=session_id)
        return _err("NOT_FOUND", "Session not found.", session_id=session_id)

    # Enforce active and not expired for access
    def _parse_dt(s):
        try:
            if isinstance(s, str) and s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s) if isinstance(s, str) else None
        except Exception:
            return None

    now_dt = datetime.datetime.utcnow()
    exp = _parse_dt(sess.get("expires_at"))
    if sess.get("status") != "active" or (exp is not None and exp <= now_dt):
        _log("CONFLICT", session_id=session_id)
        return _err("CONFLICT", "Session is not active.", session_status=sess.get("status"))

    oid = sess.get("current_order_id")
    if not oid:
        _log("NOT_FOUND", session_id=session_id)
        return _err("NOT_FOUND", "Session has no current_order_id.", session_id=session_id)

    order = next((o for o in orders if o.get("id") == oid), None)
    if not order:
        _log("NOT_FOUND", session_id=session_id, order_id=oid)
        return _err("NOT_FOUND", "Current order not found.", order_id=oid)

    # Application check: order must belong to this session
    if order.get("session_id") != session_id:
        _log("UNAUTHORIZED", session_id=session_id, order_id=oid)
        return _err("UNAUTHORIZED", "Order is not accessible to the caller.")

    live_items = [it for it in items if it.get("order_id") == oid and it.get("status") != "removed"]
    resp = {"order": order, "items": live_items}
    _log("OK", session_id=session_id, order_id=oid)
    return resp

