        return _err("UNAUTHORIZED", "Order is not accessible to this session.", order_id=order_id)

    allowed_from = ("draft", "priced", "failed", "validating")
    if order.get("status") not in allowed_from:
        _log("error", "CONFLICT", session_id=sess.get("id"), order_id_for_log=order_id,
             meta={"rule": "order must be draft/priced/failed/validating to validate", "status": order.get("status")})
