    def _log(status, code=None, session_id=None, order_id_for_log=None, meta=None):
        latency_ms = int((time.time() - t0) * 1000)
        fname = _choose_logfile()
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"dps_req_{uuid.uuid4().hex[:24]}",
            "endpoint": endpoint,
            "timestamp": _iso_now(),
            "status": status,
            "latency_ms": latency_ms,
        }
        if session_id is not None:
            row["session_id"] = session_id
        if order_id_for_log is not None:
            row["order_id"] = order_id_for_log
        if code is not None:
            row["error_code"] = code
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save(fname, logs)

    if not isinstance(order_id, str) or not order_id.strip():
        _log("error", "VALIDATION_ERROR", meta={"field": "order_id"})
        return _err("VALIDATION_ERROR", "order_id must be a non-empty string.", field="order_id")

    orders = _load("orders.json")
    if not isinstance(orders, list):
        orders = []
    order = next((o for o in orders if isinstance(o, dict) and o.get("id") == order_id), None)
    if not order:
        _log("error", "NOT_FOUND", order_id_for_log=order_id)
        return _err("NOT_FOUND", "Order not found.", order_id=order_id)

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    now = datetime.datetime.utcnow()

    def _session_ok(s):
        if not isinstance(s, dict):
            return False
        if s.get("status") != "active":
            return False
        exp = _parse_dt(s.get("expires_at"))
        if exp is not None and exp <= now:
            return False
        return True

    sess = next((s for s in sessions if _session_ok(s) and s.get("current_order_id") == order_id), None)
    if sess is None:
        sess = next((s for s in sessions if _session_ok(s) and s.get("id") == order.get("session_id")), None)
    if sess is None:
        _log("error", "UNAUTHORIZED", order_id_for_log=order_id)
        return _err("UNAUTHORIZED", "No active session is authorized for this order.", order_id=order_id)

    if order.get("session_id") != sess.get("id"):
        _log("error", "UNAUTHORIZED", session_id=sess.get("id"), order_id_for_log=order_id)
        return _err("UNAUTHORIZED", "Order is not accessible to this session.", order_id=order_id)

    if order.get("status") in ("placing", "placed", "cancelled"):
        _log("error", "CONFLICT", session_id=sess.get("id"), order_id_for_log=order_id,
             meta={"rule": "cannot price when order is placing/placed/cancelled", "status": order.get("status")})
        return _err("CONFLICT", "Order is not in a state that can be priced.", order_id=order_id, status=order.get("status"))

    order_items = _load("order_items.json")
    if not isinstance(order_items, list):
        order_items = []
    active_items = [it for it in order_items if isinstance(it, dict) and it.get("order_id") == order_id and it.get("status") == "active"]
    if len(active_items) < 1:
        _log("error", "CONFLICT", session_id=sess.get("id"), order_id_for_log=order_id,
             meta={"rule": "pricing requires at least 1 active order item"})
        return _err("CONFLICT", "Cannot price: order must have at least 1 active item.", order_id=order_id)

    if order.get("service_method") == "delivery" and not isinstance(order.get("delivery_address"), dict):
        _log("error", "CONFLICT", session_id=sess.get("id"), order_id_for_log=order_id,
             meta={"rule": "delivery orders must have delivery_address before pricing"})
        return _err("CONFLICT", "Cannot price: delivery_address is required for delivery orders.", order_id=order_id)

    # Transition to pricing
    now_iso = _iso_now()
    order["status"] = "pricing"
    order["updated_at"] = now_iso
    _save("orders.json", orders)

    # Simulated provider pricing: deterministic-ish line pricing per quantity with small randomness
    currency = (order.get("currency") or "USD")
    subtotal = 0.0
    line_results = []
    for it in active_items:
        base = 7.99  # simple fallback
        # small variation based on product_code length
        base += (len(str(it.get("product_code") or "")) % 5) * 0.5
        qty = int(it.get("quantity") or 1)
        line_total = round(base * qty, 2)
        subtotal += line_total
        line_results.append((it.get("id"), line_total))

    tax = round(subtotal * 0.0825, 2)
    fees = round(1.50 if order.get("service_method") == "delivery" else 0.75, 2)
    total = round(subtotal + tax + fees, 2)

    pricing_result = {
        "provider": "dominos",
        "priced_at": _iso_now(),
        "ok": True,
        "currency": currency,
        "subtotal": subtotal,
        "tax": tax,
        "fees": fees,
        "discounts": 0.0,
        "total": total,
        "lines": [{"order_item_id": iid, "line_total": amt} for (iid, amt) in line_results],
    }

    # Persist per-line priced_amount
    now2 = _iso_now()
    id_to_amt = {iid: amt for iid, amt in line_results}
    for it in order_items:
        if isinstance(it, dict) and it.get("order_id") == order_id and it.get("id") in id_to_amt:
            it["priced_amount"] = id_to_amt[it.get("id")]
            it["currency"] = currency
            it["updated_at"] = now2
    _save("order_items.json", order_items)

    order["pricing_result"] = pricing_result
    order["total_amount"] = total
    order["currency"] = currency
    order["error"] = None
    order["status"] = "priced"
    order["updated_at"] = _iso_now()
    _save("orders.json", orders)

    items_non_removed = [it for it in order_items if isinstance(it, dict) and it.get("order_id") == order_id and it.get("status") != "removed"]
    _log("ok", session_id=sess.get("id"), order_id_for_log=order_id)
    return {"order": order, "items": items_non_removed, "pricing_result": pricing_result}

