    orders = _load("orders.json")
    if not isinstance(orders, list):
        orders = []
    order = next((o for o in orders if isinstance(o, dict) and o.get("id") == order_id), None)
    if not order:
        _log("error", "NOT_FOUND", order_id_for_log=order_id)
