             meta={"rule": "delivery_address required for delivery placement"})
        return _err("CONFLICT", "Cannot place: delivery_address is required for delivery orders.", order_id=order_id)

    # Must have at least one active item
    order_items = _load("order_items.json")
    if not isinstance(order_items, list):
        order_items = []
    active_items = [it for it in order_items if isinstance(it, dict) and it.get("order_id") == order_id and it.get("status") == "active"]
    if len(active_items) < 1:
        _log("error", "CONFLICT", session_id=sess.get("id"), order_id_for_log=order_id,
             meta={"rule": "placement requires at least 1 active order item"})
        return _err("CONFLICT", "Cannot place: order must have at least 1 active item.", order_id=order_id)

    # Persist payment selection on order
    now_iso = _iso_now()
    order["payment_method"] = payment_method
    order["payment_payload"] = payment_payload
    order["status"] = "placing"
    order["updated_at"] = now_iso
    _save("orders.json", orders)

    # Simulated provider placement - always succeed here
    city_hint = "GEN"
    store_id = str(order.get("store_id") or "")
    if store_id:
        city_hint = (store_id[-3:] or "GEN").upper()
        city_hint = "".join([c for c in city_hint if c.isalnum()])[:3] or "GEN"
    provider_order_id = f"DPZ-{city_hint}-{random.randint(10000000, 99999999)}"
    tracking_url = f"https://tracker.dominos.com/?id={provider_order_id}"

    order["provider_order_id"] = provider_order_id
    order["provider_tracking_url"] = tracking_url
    order["placed_at"] = _iso_now()
    order["error"] = None
    order["status"] = "placed"
    order["updated_at"] = _iso_now()
    _save("orders.json", orders)

    items_non_removed = [it for it in order_items if isinstance(it, dict) and it.get("order_id") == order_id and it.get("status") != "removed"]
    _log("ok", session_id=sess.get("id"), order_id_for_log=order_id, meta={"provider_order_id": provider_order_id})
    return {"order": order, "items": items_non_removed, "provider_order_id": provider_order_id, "provider_tracking_url": tracking_url}

