def createSession(client_label=None, expires_at=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0170000" if __import__("os").path.isdir("./environment_mix/0170000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    _t0 = time.time()
    endpoint = "createSession"

    def _log(status, session_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"dps_req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "endpoint": endpoint,
            "timestamp": _iso(_now()),
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "session_id": session_id,
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        if client_label is not None and not isinstance(client_label, str):
            _log("error", extra={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "client_label must be a string")

        now = _now()
        exp = None
        if expires_at is None:
            exp = now + datetime.timedelta(hours=2)
        else:
            exp = _parse_dt(expires_at)
            if exp is None:
                _log("error", extra={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "expires_at must be RFC3339 date-time string")
            if exp.tzinfo is None:
                exp = exp.replace(tzinfo=datetime.timezone.utc)
            # Constraint: expires_at > created_at
            if exp <= now:
                _log("error", extra={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "expires_at must be in the future")

        sessions = _load("sessions.json")
        if not isinstance(sessions, list):
            sessions = []

        # ULID-like id (not strict ULID, but matches prefix convention)
        sid = f"dps_sess_{int(time.time()*1000)}_{random.randint(100000,999999)}"
        sess = {
            "id": sid,
            "status": "active",
            "client_label": client_label,
            "current_store_id": None,
            "current_order_id": None,
            "expires_at": _iso(exp),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }

        sessions.append(sess)
        _save("sessions.json", sessions)

        _log("ok", session_id=sid)
        return {"session": sess}
    except Exception as e:
        try:
            _log("error", extra={"code": "INTERNAL_ERROR", "detail": str(e)})
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "Unexpected error")

def updateSession(session_id, status=None, client_label=None, current_store_id=None, current_order_id=None, expires_at=None, **_extra):
    import json, os, datetime, time, random

